const { readFile, writeFile } = require("node:fs/promises");

async function ajouterVisite() {
  // utf8 demande directement une chaîne plutôt qu’un Buffer.
  const texte = await readFile("./stats.json", "utf8");
  // Le fichier est du texte : on le transforme en objet JavaScript.
  const stats = JSON.parse(texte);
  stats.visites += 1;
  // On réécrit un JSON lisible avec deux espaces d’indentation.
  await writeFile("./stats.json", JSON.stringify(stats, null, 2));
}

// Une erreur de lecture ou d’écriture est traitée ici.
ajouterVisite().catch(console.error);
